// setSource decodes the input s into code points and, if s is valid UTF-8, records the offset
// table for token text, all in one pass (a U+FFFD that decodes from three bytes is valid).
func (p *parser) setSource(s string) {
	n := utf8.RuneCountInString(s)
	// The buffers of a parser used before are reused (the typed runtime keeps parsers).
	if cap(p.in) >= n {
		p.in = p.in[:n]
	} else {
		p.in = make([]rune, n)
	}
	p.n = n
	offs := p.offs[:0]
	if cap(offs) >= n+1 {
		offs = offs[:n+1]
	} else {
		offs = make([]int32, n+1)
	}
	valid := len(s) <= 1<<31-1
	i := 0
	for off, r := range s {
		if r == utf8.RuneError && valid {
			if _, size := utf8.DecodeRuneInString(s[off:]); size == 1 {
				valid = false
			}
		}
		p.in[i] = r
		offs[i] = int32(off)
		i++
	}
	offs[n] = int32(len(s))
	if valid {
		p.src, p.offs = s, offs
	} else {
		p.offs = nil
	}
}

// peek returns the character at the current position and its size in units.
func (p *parser) peek() (rune, int, bool) {
	if p.pos >= p.n {
		return 0, 0, false
	}
	if p.unit == Bytes {
		if c := p.bs[p.pos]; c < utf8.RuneSelf {
			return rune(c), 1, true
		}
		r, size := utf8.DecodeRuneInString(p.bs[p.pos:])
		return r, size, true
	}
	return p.in[p.pos], 1, true
}

func (p *parser) unitLen(s string) int {
	if p.unit == Bytes {
		return len(s)
	}
	return utf8.RuneCountInString(s)
}

// expect records that id was expected at pos.
func (p *parser) expect(pos int, id expID) {
	if p.silent > 0 || pos < p.farthest {
		return
	}
	if pos > p.farthest {
		p.farthest = pos
		p.exp = p.exp[:p.expBase]
	}
	for _, e := range p.exp[p.expBase:] {
		if e == id {
			return
		}
	}
	p.exp = append(p.exp, id)
}

// expMark is the expectation record before isolate.
type expMark struct{ far, base int }

// isolate starts a separate expectation record whose farthest position is pos.
func (p *parser) isolate(pos int) expMark {
	m := expMark{p.farthest, p.expBase}
	p.expBase, p.farthest = len(p.exp), pos
	return m
}

// unisolate ends the separate record and returns its farthest position and expectations. The
// expectations alias the stack and are valid only until the next record (passing them to
// mergeExpected is fine; keep copies them).
func (p *parser) unisolate(m expMark) (far int, inner []expID) {
	far, inner = p.farthest, p.exp[p.expBase:]
	p.exp = p.exp[:p.expBase]
	p.expBase, p.farthest = m.base, m.far
	return far, inner
}

// keep copies ids into the append-only arena.
func (p *parser) keep(ids []expID) []expID {
	if len(ids) == 0 {
		return nil
	}
	if slicesEqual(ids, p.lastKept) { // the same set often repeats
		return p.lastKept
	}
	if cap(p.arena)-len(p.arena) < len(ids) {
		// A new chunk; the previous one lives while slices into it remain.
		p.arena = make([]expID, 0, max(1024, len(ids)))
	}
	off := len(p.arena)
	p.arena = append(p.arena, ids...)
	p.lastKept = p.arena[off:len(p.arena):len(p.arena)]
	return p.lastKept
}

func slicesEqual(a, b []expID) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// mergeExpected records the expectations ids at far. ids may alias the stack above the
// current record (writes only happen below the read position).
func (p *parser) mergeExpected(far int, ids []expID) {
	for _, x := range ids {
		p.expect(far, x)
	}
}

func (p *parser) text(start, end int) string {
	if p.unit == Bytes {
		return p.bs[start:end]
	}
	if p.offs != nil {
		return p.src[p.offs[start]:p.offs[end]]
	}
	return string(p.in[start:end])
}

type fatal struct{ err error }

func (p *parser) makeError(pos int, expected []expID) *SyntaxError {
	e := &SyntaxError{Pos: pos}
	for _, x := range expected {
		if x&msgBit != 0 {
			e.Messages = append(e.Messages, descs[x&^msgBit])
		} else {
			e.Expected = append(e.Expected, descs[x])
		}
	}
	sort.Strings(e.Expected)
	// Look the line up in a table of line starts, built on the first error, instead of scanning
	// from the start of the input for each error.
	if p.lines == nil {
		p.lines = append(p.lines, 0)
		for i := 0; i < p.n; i++ {
			if p.unit == Bytes && p.bs[i] == '\n' || p.unit == CodePoints && p.in[i] == '\n' {
				p.lines = append(p.lines, i+1)
			}
		}
	}
	pos = min(pos, p.n)
	i := sort.SearchInts(p.lines, pos+1)
	e.Line, e.Col = i, pos-p.lines[i-1]+1
	return e
}

// --- Rule calls ---

// call calls rule r at level min.
func (p *parser) call(r *rule, min int) (*Node, bool) {
	start := p.pos
	if !r.memo && !r.leader || p.firstCall(r) {
		// Unmemoized call: no memo bookkeeping, and expectations need no isolation.
		if len(r.scope) == 0 {
			return p.invokePlain(r, min)
		}
		rec := len(p.recovered)
		v, ok := p.invoke(r, min)
		if !ok {
			p.pos = start
			p.recovered = p.recovered[:rec]
		}
		return v, ok
	}
	env := p.envValues(r.vars)
	// See the engine's callBegin: entries with recovered errors are reused only in the same kind of
	// context (inside or outside a lookahead) they were computed in.
	if e := p.memo.get(r.id, start, min, env); e != nil && (e.growing || (!e.silent || p.silent > 0) && (len(e.errs) == 0 || e.silent == (p.silent > 0))) {
		if !e.growing {
			p.mergeExpected(e.far, e.expected)
		}
		if !e.ok {
			return nil, false
		}
		p.pos = e.end
		p.recovered = append(p.recovered, e.errs...)
		return e.node, true
	}
	rec := len(p.recovered)
	// The memoized result includes the expectations recorded in this call.
	m := p.isolate(start)
	var v *Node
	var ok bool
	var e *memoEntry
	if r.leader {
		v, ok = p.grow(r, min, env)
		e = p.memo.get(r.id, start, min, env)
	} else {
		v, ok = p.invoke(r, min)
		if !ok {
			p.recovered = p.recovered[:rec]
		}
		e = p.memo.alloc()
		*e = memoEntry{node: v, ok: ok, end: p.pos, silent: p.silent > 0,
			errs: append([]*SyntaxError(nil), p.recovered[rec:]...)}
		p.memo.put(r.id, start, min, env, e)
	}
	far, inner := p.unisolate(m)
	e.far, e.expected = far, p.keep(inner)
	p.mergeExpected(far, inner)
	if !ok {
		p.pos = start
	}
	return v, ok
}

// grow grows the seed of a left-recursive leader: it memoizes a failure, then evaluates the
// body again while the match gets longer, and keeps the last longer result.
func (p *parser) grow(r *rule, min int, env []any) (*Node, bool) {
	start := p.pos
	rec := len(p.recovered)
	best := p.memo.alloc()
	*best = memoEntry{end: start, growing: true}
	p.memo.put(r.id, start, min, env, best)
	for {
		v, ok := p.invoke(r, min)
		if !ok || (best.ok && p.pos <= best.end) {
			break
		}
		best = p.memo.alloc()
		*best = memoEntry{node: v, ok: true, end: p.pos, growing: true, errs: append([]*SyntaxError(nil), p.recovered[rec:]...)}
		p.memo.put(r.id, start, min, env, best)
		p.pos = start
		p.recovered = p.recovered[:rec]
	}
	best.growing = false
	best.silent = p.silent > 0
	p.pos = best.end
	p.recovered = append(p.recovered[:rec], best.errs...)
	return best.node, best.ok
}

// invoke evaluates the body of r and makes the rule's value.
func (p *parser) invoke(r *rule, min int) (*Node, bool) {
	f := p.newFrame(len(r.scope))
	prevFrame, prevEnv, prevCut, trail := p.frame, p.env, p.cut, len(p.trail)
	p.frame, p.cut = f, false
	p.depth++
	if p.depth > maxDepth {
		panic(fatal{fmt.Errorf("nesting too deep: more than %d rule calls", maxDepth)})
	}
	start := p.pos
	v, ok := r.body(p, min)
	p.depth--
	p.frame, p.cut = prevFrame, prevCut
	p.trail = p.trail[:trail]
	if ok {
		v = p.finish(r, f, v, start)
	}
	p.env = prevEnv
	return v, ok
}

// invokePlain is an unmemoized call of a rule without captures: invoke without the capture
// frame (the body never writes one, so the caller's stays current), with the failure handling of
// call.
func (p *parser) invokePlain(r *rule, min int) (*Node, bool) {
	start, rec, trail := p.pos, len(p.recovered), len(p.trail)
	prevEnv, prevCut := p.env, p.cut
	p.cut = false
	p.depth++
	if p.depth > maxDepth {
		p.tooDeep()
	}
	v, ok := r.body(p, min)
	p.depth--
	p.cut = prevCut
	p.trail = p.trail[:trail]
	if ok {
		v = p.finish(r, emptyFrame, v, start)
	} else {
		p.pos = start
		p.recovered = p.recovered[:rec]
	}
	p.env = prevEnv
	return v, ok
}

// tooDeep fails the parse for exceeding the nesting limit.
func (p *parser) tooDeep() {
	panic(fatal{fmt.Errorf("nesting too deep: more than %d rule calls", maxDepth)})
}

// finish makes the rule's value from the value of its body.
func (p *parser) finish(r *rule, f *frame, v *Node, start int) *Node {
	if r.novalue {
		return nil
	}
	if r.action != nil {
		c := p.useCtx(actx{p: p, f: f, start: start, end: p.pos, cbase: len(p.created)})
		if r.bodyIsSeq && v != nil {
			c.items = v.Children
		} else {
			c.one[0] = v
			c.items = c.one[:]
		}
		return c.result(r.action, r.name)
	}
	if r.terminalType != "" {
		return p.newNode(Node{Type: r.terminalType, Rule: r.name, Start: start, End: p.pos, Text: p.text(start, p.pos), terminal: true})
	}
	if len(r.scope) > 0 {
		v = p.attachCaptures(v, r.scope, f, start, p.pos)
	}
	if v == nil {
		return nil
	}
	if v.fresh {
		if v.Rule == "" {
			v.Rule = r.name
		}
		v.fresh = false
	}
	return v
}

// attachCaptures attaches the non-nil captures as fields of the node. A node of another rule, or
// one that is itself captured, is first wrapped in a Seq node.
func (p *parser) attachCaptures(v *Node, names []string, f *frame, start, end int) *Node {
	found := false
	wrap := v == nil || !v.fresh
	for _, c := range f.vals {
		if c != nil {
			found = true
		}
		if c != nil && c == v {
			wrap = true
		}
	}
	if !found {
		return v
	}
	if wrap {
		v = p.newNode(Node{Type: "Seq", Start: start, End: end, Children: append(p.nodes(1)[:0], v), fresh: true})
	}
	if v.Fields == nil {
		v.Fields = p.fields(len(names))
	}
	for i, name := range names {
		if f.vals[i] != nil {
			v.Fields.set(name, f.vals[i])
		}
	}
	return v
}

func nodeOrNil(n *Node) any {
	if n == nil {
		return nil
	}
	return n
}

// --- Terminals ---

func (p *parser) matchLiteral(rs []rune, text string, desc expID, build bool) (*Node, bool) {
	start := p.pos
	if p.unit == Bytes {
		if !strings.HasPrefix(p.bs[p.pos:], text) {
			p.expect(start, desc)
			return nil, false
		}
		p.pos += len(text)
	} else {
		for _, r := range rs {
			if p.pos >= p.n || p.in[p.pos] != r {
				p.expect(start, desc)
				return nil, false
			}
			p.pos++
		}
	}
	if !build {
		return nil, true
	}
	return p.newNode(Node{Type: "Match", Start: start, End: p.pos, Text: text, terminal: true, fresh: true}), true
}

func (p *parser) matchAny(build bool) (*Node, bool) {
	_, size, ok := p.peek()
	if !ok {
		p.expect(p.pos, idAny)
		return nil, false
	}
	return p.single(size, build)
}

// single consumes one character of size units.
func (p *parser) single(size int, build bool) (*Node, bool) {
	start := p.pos
	p.pos += size
	if !build {
		return nil, true
	}
	return p.newNode(Node{Type: "Match", Start: start, End: p.pos, Text: p.text(start, p.pos), terminal: true, fresh: true}), true
}

func (p *parser) anchor(ok bool, desc expID) (*Node, bool) {
	if ok {
		return nil, true
	}
	p.expect(p.pos, desc)
	return nil, false
}

func (p *parser) atLineStart() bool {
	if p.pos == 0 {
		return true
	}
	if p.unit == Bytes {
		return p.bs[p.pos-1] == '\n'
	}
	return p.in[p.pos-1] == '\n'
}

func (p *parser) atLineEnd() bool {
	ch, _, ok := p.peek()
	return !ok || ch == '\n' || ch == '\r'
}

func (p *parser) atEnd() bool { return p.pos == p.n }

// --- Attributes ---

type matcher = func(p *parser) (*Node, bool)

// tracked runs m with a separate expectation record and returns its farthest position and
// expectations (valid only until the next record; see unisolate).
func (p *parser) tracked(m matcher) (v *Node, ok bool, far int, expected []expID) {
	mark := p.isolate(p.pos)
	v, ok = m(p)
	far, expected = p.unisolate(mark)
	return v, ok, far, expected
}

// errorAttr replaces the expectations of a failing m with the message msg (an ID with msgBit),
// reported at the farthest position m reached.
func (p *parser) errorAttr(m matcher, msg expID) (*Node, bool) {
	v, ok, far, expected := p.tracked(m)
	if ok {
		p.mergeExpected(far, expected)
		return v, true
	}
	p.expect(far, msg)
	return nil, false
}

// recoverAttr records the error of a failing m, skips what skip matches and returns an Error
// node. It fails without recovering when skip fails or skips nothing.
func (p *parser) recoverAttr(m, skip matcher, build bool) (*Node, bool) {
	m0 := p.mark()
	v, ok, far, expected := p.tracked(m)
	if ok {
		p.mergeExpected(far, expected)
		return v, true
	}
	expected = p.keep(expected) // keep them while skipping
	p.reset(m0)
	if _, ok := skip(p); !ok || p.pos == m0.pos {
		p.reset(m0)
		p.mergeExpected(far, expected)
		return nil, false
	}
	e := p.makeError(far, expected)
	p.recovered = append(p.recovered, e)
	if !build {
		return nil, true
	}
	return p.newNode(Node{Type: "Error", Start: m0.pos, End: p.pos, Text: p.text(m0.pos, p.pos),
		Fields: Fields{{"message", e.Error()}}, fresh: true, terminal: true}), true
}

// --- Actions and predicates ---

// evalError is an error in evaluating a value expression. It fails the whole parse in an action and
// makes a predicate fail.
type evalError struct{ msg string }

func evalErrorf(format string, args ...any) { panic(evalError{fmt.Sprintf(format, args...)}) }

// actx is the context of evaluating an action or a predicate.
type actx struct {
	p            *parser
	f            *frame
	items        []*Node
	start, end   int
	cbase        int // start of p.created made by this evaluation
	lhs, rhs, op any
	one          [1]*Node // backing array of items for a single item
}

// useCtx places the evaluation context in the parser's single context and returns it.
// Evaluations never nest, and no reference to the context survives one (function values
// cannot be stored in fields or variables), so one context per parser can be reused.
func (p *parser) useCtx(c actx) *actx {
	p.ac = c
	return &p.ac
}

func (c *actx) result(action func(*actx) any, where string) (n *Node) {
	defer func() {
		if x := recover(); x != nil {
			e, ok := x.(evalError)
			if !ok {
				panic(x)
			}
			panic(fatal{fmt.Errorf("action in %s: %s", where, e.msg)})
		}
	}()
	v := action(c)
	if v == nil {
		return nil
	}
	n, ok := v.(*Node)
	if !ok {
		evalErrorf("result must be a node, got %s", typeName(v))
	}
	for _, x := range c.p.created[c.cbase:] {
		if x == n {
			n.Start, n.End = c.start, c.end
			break
		}
	}
	c.p.created = c.p.created[:c.cbase]
	if n != nil {
		n.fresh = false // the value of an action is final (see the engine's actionResult)
	}
	return n
}

func (p *parser) predicate(t func(*actx) any) (ok bool) {
	base, kids := len(p.created), len(p.kidStack)
	defer func() {
		p.created = p.created[:base] // drop nodes created by the predicate
		if x := recover(); x != nil {
			if _, isEval := x.(evalError); !isEval {
				panic(x)
			}
			p.dropKids(kids) // elements gathered by a list built-in that failed
			ok = false
		}
	}()
	c := p.useCtx(actx{p: p, f: p.frame, start: p.pos, end: p.pos, cbase: len(p.created)})
	v := t(c)
	if b, isBool := v.(bool); isBool && !b {
		return false
	}
	return true
}

func (p *parser) assign(name string, t func(*actx) any) (ok bool) {
	base, kids := len(p.created), len(p.kidStack)
	defer func() {
		p.created = p.created[:base] // drop nodes created by the predicate
		if x := recover(); x != nil {
			if _, isEval := x.(evalError); !isEval {
				panic(x)
			}
			p.dropKids(kids) // elements gathered by a list built-in that failed
			ok = false
		}
	}()
	c := p.useCtx(actx{p: p, f: p.frame, start: p.pos, end: p.pos, cbase: len(p.created)})
	v := t(c)
	if _, isFn := v.(func(...any) any); isFn {
		return false
	}
	p.env = &env{name: name, val: v, next: p.env}
	return true
}

func (c *actx) cap(slot int) any { return nodeOrNil(c.f.vals[slot]) }

func (c *actx) item(n int) any {
	if n == 0 {
		return c.newList(c.items)
	}
	if n > len(c.items) {
		evalErrorf("$%d is out of range (%d elements)", n, len(c.items))
	}
	return nodeOrNil(c.items[n-1])
}

func (c *actx) lookup(name string) any {
	for e := c.p.env; e != nil; e = e.next {
		if e.name == name {
			return e.val
		}
	}
	evalErrorf("variable %s is not defined", name)
	return nil
}

func typeName(v any) string {
	switch v := v.(type) {
	case nil:
		return "nil"
	case *Node:
		if v == nil {
			return "nil"
		}
		return v.Type
	case int:
		return "int"
	case string:
		return "string"
	case bool:
		return "bool"
	}
	return fmt.Sprintf("%T", v)
}

func (c *actx) newStruct(typ string, kv ...any) any {
	n := c.p.newNode(Node{Type: typ, Fields: c.p.fields(len(kv) / 2)})
	first := true
	for i := 0; i < len(kv); i += 2 {
		v := kv[i+1]
		n.Fields.set(kv[i].(string), v)
		if child, ok := v.(*Node); ok && child != nil {
			if first || child.Start < n.Start {
				n.Start = child.Start
			}
			if first || child.End > n.End {
				n.End = child.End
			}
			first = false
		}
	}
	if first {
		n.Start, n.End = c.start, c.end
	}
	c.p.created = append(c.p.created, n)
	return n
}

func (c *actx) newList(items []*Node) *Node {
	return c.listNode(append(c.p.nodes(len(items))[:0], items...))
}

// listNode returns a List node with the child list kids (which it takes over).
func (c *actx) listNode(kids []*Node) *Node {
	n := c.p.newNode(Node{Type: "List", Children: kids, Start: c.start, End: c.start})
	first := true
	for _, it := range kids {
		if it == nil {
			continue
		}
		if first || it.Start < n.Start {
			n.Start = it.Start
		}
		if first || it.End > n.End {
			n.End = it.End
		}
		first = false
	}
	return n
}

func (c *actx) member(x any, name string) any {
	n, ok := x.(*Node)
	if !ok || n == nil {
		evalErrorf("cannot access .%s of %s", name, typeName(x))
	}
	switch name {
	case "startPos":
		return n.Start
	case "endPos":
		return n.End
	case "children":
		return c.newList(n.Children)
	}
	if fields, ok := structFields[n.Type]; ok && !fields[name] {
		evalErrorf("%s has no field %s", n.Type, name)
	}
	v, _ := n.Fields.Get(name)
	return v
}

func rtUnary(op string, x any) any {
	switch op {
	case "-":
		if i, ok := x.(int); ok {
			return -i
		}
	case "!":
		if b, ok := x.(bool); ok {
			return !b
		}
	}
	evalErrorf("invalid operand %s for unary %s", typeName(x), op)
	return nil
}

func rtBool(op string, v any) bool {
	b, ok := v.(bool)
	if !ok {
		evalErrorf("invalid operand %s for %s", typeName(v), op)
	}
	return b
}

func rtAnd(l any, r func() any) any {
	if !rtBool("&&", l) {
		return false
	}
	return rtBool("&&", r())
}

func rtOr(l any, r func() any) any {
	if rtBool("||", l) {
		return true
	}
	return rtBool("||", r())
}

func rtEqual(a, b any) bool {
	switch a := a.(type) {
	case *Node:
		if a == nil {
			return b == nil
		}
		bn, ok := b.(*Node)
		return ok && a == bn
	case nil:
		if bn, ok := b.(*Node); ok {
			return bn == nil
		}
		return b == nil
	case int, string, bool:
		return a == b
	}
	return false
}

func rtBinary(op string, l, r any) any {
	switch op {
	case "==":
		return rtEqual(l, r)
	case "!=":
		return !rtEqual(l, r)
	}
	switch l := l.(type) {
	case int:
		if r, ok := r.(int); ok {
			switch op {
			case "+":
				return l + r
			case "-":
				return l - r
			case "*":
				return l * r
			case "/", "%":
				if r == 0 {
					evalErrorf("division by zero")
				}
				if op == "/" {
					return l / r
				}
				return l % r
			case "<":
				return l < r
			case "<=":
				return l <= r
			case ">":
				return l > r
			case ">=":
				return l >= r
			}
		}
	case string:
		if r, ok := r.(string); ok {
			switch op {
			case "+":
				return l + r
			case "<":
				return l < r
			case "<=":
				return l <= r
			case ">":
				return l > r
			case ">=":
				return l >= r
			}
		}
	}
	evalErrorf("invalid operands %s and %s for %s", typeName(l), typeName(r), op)
	return nil
}

func (c *actx) length(x any) any {
	switch x := x.(type) {
	case string:
		return c.p.unitLen(x)
	case *Node:
		if x == nil {
			return 0
		}
		if x.terminal {
			return c.p.unitLen(x.Text)
		}
		return len(x.Children)
	case nil:
		return 0
	}
	evalErrorf("len: invalid argument %s", typeName(x))
	return nil
}

func (c *actx) text(x any) any { return c.textStr(x) }

// textStr returns text(x) as a string. Comparisons of two texts use it directly, since storing a
// string in an interface allocates.
func (c *actx) textStr(x any) string {
	switch x := x.(type) {
	case nil:
		return ""
	case string:
		return x
	case *Node:
		if x == nil {
			return ""
		}
		if x.terminal {
			return x.Text
		}
		return c.p.text(x.Start, x.End)
	}
	evalErrorf("text: invalid argument %s", typeName(x))
	return ""
}

func listItems(fn string, v any) []*Node {
	switch x := v.(type) {
	case nil:
		return nil
	case *Node:
		if x == nil {
			return nil
		}
		return x.Children
	}
	evalErrorf("%s: expected a list, got %s", fn, typeName(v))
	return nil
}

func asNode(fn string, v any) *Node {
	switch x := v.(type) {
	case nil:
		return nil
	case *Node:
		return x
	}
	evalErrorf("%s: list elements must be nodes, got %s", fn, typeName(v))
	return nil
}

func rtFold(fn string, right bool, acc, list any, f func(acc, item any) any) any {
	items := listItems(fn, list)
	for i := range items {
		it := items[i]
		if right {
			it = items[len(items)-1-i]
		}
		acc = f(acc, nodeOrNil(it))
	}
	return acc
}

// The list built-ins gather the elements on kidStack (lambdas that build lists push above them)
// and hand the copied-out slice to the list node. If one fails, the error unwinds to the action
// (which fails the parse) or the predicate (which pops what was gathered).

func (c *actx) mapList(list any, f func(item any) any) any {
	base := len(c.p.kidStack)
	c.pushMap(list, f)
	return c.endList(base)
}

func (c *actx) list(args ...any) any {
	base := len(c.p.kidStack)
	c.pushList(args...)
	return c.endList(base)
}

func (c *actx) concat(args ...any) any {
	base := len(c.p.kidStack)
	for _, a := range args {
		c.pushItems(a)
	}
	return c.endList(base)
}

// pushMap, pushList and pushItems push the elements that map, list and concat make from their
// arguments. A concat call whose arguments are all list, map or such concat calls is generated
// as pushes for its arguments followed by endList, so that they build no intermediate list.

func (c *actx) pushMap(list any, f func(item any) any) {
	for _, it := range listItems("map", list) {
		c.p.kidStack = append(c.p.kidStack, asNode("map", f(nodeOrNil(it))))
	}
}

func (c *actx) pushList(args ...any) {
	for _, a := range args {
		c.p.kidStack = append(c.p.kidStack, asNode("list", a))
	}
}

func (c *actx) pushItems(v any) {
	c.p.kidStack = append(c.p.kidStack, listItems("concat", v)...)
}

// endList returns a list of the elements pushed since base.
func (c *actx) endList(base int) any {
	return c.listNode(c.p.kids(base))
}

// --- Pratt expressions ---

type pratt struct {
	skip     matcher
	operands []*prattLine
	prefix   []*prattOp
	led      []*prattOp
}

type prattLine struct {
	scope  []string
	m      matcher
	action func(*actx) any
	isSeq  bool
}

type prattOp struct {
	id    int
	kind  string
	assoc string
	level int
	line  *prattLine
}

type prattAttempt struct {
	op         *prattOp
	frame      *frame
	v          *Node
	start, end int
	env        *env
	cut        bool
	errs       []*SyntaxError
}

func (p *parser) skipTrivia(pr *pratt) {
	if pr.skip == nil {
		return
	}
	m := p.mark()
	p.silent++
	_, ok := pr.skip(p)
	p.silent--
	if !ok {
		p.reset(m)
	}
}

// longest tries every operator and returns the longest match (the first declared among equals);
// best.op is nil when none matched. cutFailed reports a candidate that failed after a cut. The
// attempt is returned by value, so trying operators allocates nothing for lines without captures.
func (p *parser) longest(ops []*prattOp) (best prattAttempt, cutFailed bool) {
	m0 := p.mark()
	for _, op := range ops {
		prevFrame, prevCut := p.frame, p.cut
		f := p.newFrame(len(op.line.scope))
		p.frame, p.cut = f, false
		v, ok := op.line.m(p)
		cut := p.cut
		p.frame, p.cut = prevFrame, prevCut
		if ok && p.pos == m0.pos && op.kind != "infix" {
			ok = false // an empty prefix or postfix match could be applied forever
		}
		if ok && (best.op == nil || p.pos > best.end) {
			best = prattAttempt{op: op, frame: f, v: v, start: m0.pos, end: p.pos, env: p.env, cut: cut,
				errs: append([]*SyntaxError(nil), p.recovered[m0.recovered:]...)}
		}
		if !ok && cut {
			cutFailed = true
		}
		if len(f.vals) == 0 {
			p.reset(m0)
			continue
		}
		// reset undoes this candidate's captures; restore them. Nothing parses between saving
		// and restoring, so one buffer per parser suffices.
		p.saved = append(p.saved[:0], f.vals...)
		p.reset(m0)
		copy(f.vals, p.saved)
	}
	return best, cutFailed
}

func (p *parser) apply(a *prattAttempt) {
	p.pos, p.env = a.end, a.env
	p.recovered = append(p.recovered, a.errs...)
}

func (p *parser) prattParse(r *rule, min int) (*Node, bool) {
	pr := r.pratt
	lhs, ok := p.prattNud(r)
	if !ok {
		return nil, false
	}
	lastNone := -1
	for {
		m0 := p.mark()
		p.skipTrivia(pr)
		a, cutFailed := p.longest(pr.led)
		if a.op == nil {
			p.reset(m0)
			if cutFailed {
				return nil, false
			}
			break
		}
		if a.op.level <= min || a.op.assoc == "none" && a.op.level == lastNone {
			p.reset(m0)
			break
		}
		p.apply(&a)
		if a.op.kind == "postfix" {
			lhs = p.prattBuild(r, &a, lhs, nil)
			lastNone = -1
			continue
		}
		rmin := a.op.level
		if a.op.assoc == "right" {
			rmin--
		}
		rhs, ok := p.prattParse(r, rmin)
		if !ok {
			if a.cut {
				return nil, false
			}
			p.reset(m0)
			break
		}
		lhs = p.prattBuild(r, &a, lhs, rhs)
		lastNone = -1
		if a.op.assoc == "none" {
			lastNone = a.op.level
		}
	}
	return lhs, true
}

func (p *parser) prattNud(r *rule) (*Node, bool) {
	pr := r.pratt
	p.skipTrivia(pr)
	m0 := p.mark()
	if a, _ := p.longest(pr.prefix); a.op != nil {
		p.apply(&a)
		rhs, ok := p.prattParse(r, a.op.level)
		if ok {
			return p.prattBuild(r, &a, nil, rhs), true
		}
		if a.cut {
			return nil, false
		}
		p.reset(m0)
	}
	for _, o := range pr.operands {
		prevFrame, prevCut := p.frame, p.cut
		f := p.newFrame(len(o.scope))
		p.frame, p.cut = f, false
		v, ok := o.m(p)
		cut := p.cut
		p.frame, p.cut = prevFrame, prevCut
		if ok {
			return p.lineResult(r, o, f, v, m0.pos), true
		}
		p.reset(m0)
		if cut {
			return nil, false
		}
	}
	return nil, false
}

func (p *parser) lineResult(r *rule, l *prattLine, f *frame, v *Node, start int) *Node {
	if r.novalue {
		return nil
	}
	if l.action != nil {
		c := p.useCtx(actx{p: p, f: f, start: start, end: p.pos, cbase: len(p.created)})
		if l.isSeq && v != nil {
			c.items = v.Children
		} else {
			c.one[0] = v
			c.items = c.one[:]
		}
		return c.result(l.action, r.name)
	}
	if len(l.scope) > 0 {
		v = p.attachCaptures(v, l.scope, f, start, p.pos)
	}
	if v != nil && v.fresh {
		if v.Rule == "" {
			v.Rule = r.name
		}
		v.fresh = false
	}
	return v
}

func (p *parser) prattBuild(r *rule, a *prattAttempt, lhs, rhs *Node) *Node {
	if r.novalue {
		return nil
	}
	start, end := a.start, p.pos
	if lhs != nil {
		start = lhs.Start
	}
	if a.op.kind == "postfix" {
		end = a.end
	}
	l := a.op.line
	if l.action != nil {
		op := p.newNode(Node{Type: "Match", Start: a.start, End: a.end, Text: p.text(a.start, a.end), terminal: true})
		c := p.useCtx(actx{p: p, f: a.frame, start: start, end: end, cbase: len(p.created),
			op: op, lhs: nodeOrNil(lhs), rhs: nodeOrNil(rhs)})
		return c.result(l.action, r.name)
	}
	opv := a.v
	if len(l.scope) > 0 {
		opv = p.attachCaptures(opv, l.scope, a.frame, a.start, a.end)
	}
	if opv != nil {
		opv.fresh = false
	}
	var kids []*Node
	switch a.op.kind {
	case "prefix":
		kids = p.nodes(2)
		kids[0], kids[1] = opv, rhs
	case "postfix":
		kids = p.nodes(2)
		kids[0], kids[1] = lhs, opv
	default:
		kids = p.nodes(3)
		kids[0], kids[1], kids[2] = lhs, opv, rhs
	}
	return p.newNode(Node{Type: "Operator", Rule: r.name, Start: start, End: end, Children: kids, Fields: Fields{{"operator", a.op.id}}})
}

